(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.025+t*0.15)*8+Math.cos(mx*0.02-t*0.1)*6;
  const w2y = Math.cos(mx*0.025-t*0.12)*8+Math.sin(my*0.022+t*0.18)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.0],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*40,0.11,2.1,7.2],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75+4)*50,0.075,1.8,8.4]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    hrm+=Math.sin(d*f*1.3-t*sp*0.4+ph*0.5)*0.5;
  }
  const act=aS/8,inh=iS/8,h=hrm/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.06)*Math.sin(sy*0.06)*Math.cos(t*0.7)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.03-ang*6+t*0.8)*0.2;
  const spiral=sp1+sp2;
  const g1=Math.sin(sx*0.2)*Math.sin(sy*0.2);
  const g2=Math.sin((sx+5)*0.19)*Math.sin((sy+3)*0.19);
  const moire=(g1+g2)*0.15;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+h*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.65+cell*0.2+moire*0.15,v=blend*0.5+0.5;
  const pal=[[5,12,55],[12,45,95],[18,85,120],[25,130,130],[45,165,120],[140,190,80],[210,185,55],[220,140,60],[195,90,65],[150,50,60],[90,25,55],[45,15,50],[5,12,55]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const glow=Math.max(0,Math.abs(reaction)-0.5)*0.6;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const tl=lum*edge+glow;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*tl)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*tl)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*tl)|0];
}
